// Build Search Plan
// Reads the Settings tab into a config object and emits one item per Himalayas search page.
// The config travels on every item so later nodes can read it via $('Build Search Plan').first().json.config

const list = (v) => String(v || '').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);

const s = {};
for (const { json } of $('Read Settings').all()) {
  if (json.Setting) s[String(json.Setting).trim()] = String(json.Value ?? '').trim();
}

const prompts = {};
for (const { json } of $('Read Prompts').all()) {
  if (json['Prompt Name']) prompts[String(json['Prompt Name']).trim()] = String(json['Prompt Text'] || '');
}

const outreachPromptName = s.outreach_prompt || 'v1_warm';
if (!prompts[outreachPromptName]) {
  throw new Error(`Settings > outreach_prompt is "${outreachPromptName}" but no row with that Prompt Name exists in the Prompts tab.`);
}
if (!prompts.validation) throw new Error('The Prompts tab needs a row named "validation".');

const config = {
  searchQueries: list(s.search_queries),
  pagesPerQuery: Math.max(1, Math.min(5, parseInt(s.himalayas_pages_per_query, 10) || 2)),
  includeKeywords: list(s.title_include_keywords),
  excludeKeywords: list(s.title_exclude_keywords),
  excludedCompanies: list(s.excluded_companies),
  excludeAgencies: String(s.exclude_agencies || 'TRUE').toUpperCase() !== 'FALSE',
  maxAgeDays: parseInt(s.max_posting_age_days, 10) || 30,
  maxJobsPerRun: parseInt(s.max_jobs_per_run, 10) || 15,
  validationModel: s.validation_model || 'nvidia/nemotron-3-ultra-550b-a55b:free',
  outreachModel: s.outreach_model || 'nvidia/nemotron-3-ultra-550b-a55b:free',
  fallbackModel: s.fallback_model || '',
  backupModel: s.backup_model || '@cf/openai/gpt-oss-120b',
  outreachPromptName,
  outreachPrompt: prompts[outreachPromptName],
  validationPrompt: prompts.validation,
  sender: {
    sender_name: s.sender_name || '',
    sender_company: s.sender_company || '',
    sender_offer: s.sender_offer || '',
    call_to_action: s.call_to_action || '',
  },
};

if (!config.searchQueries.length) throw new Error('Settings > search_queries is empty.');

const out = [];
for (const q of config.searchQueries) {
  for (let page = 1; page <= config.pagesPerQuery; page++) out.push({ json: { q, page, config } });
}
return out;

// Normalize & Filter
// 1. Converts the three job-board formats into one schema.
// 2. Applies the cheap keyword / company / age filters from Settings.
// 3. Skips jobs already in the Leads or Rejected tabs (no duplicates, no wasted LLM calls).
// Outputs ONE item: { stats, candidates[], scraped[] }.

const config = $('Build Search Plan').first().json.config;
const now = Date.now();

const decode = (t) => String(t || '')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#0?39;|&apos;|&#8217;/g, "'")
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)));
const htmlToText = (html) => decode(decode(html)
  .replace(/<\s*br\s*\/?>/gi, '\n')
  .replace(/<\s*li[^>]*>/gi, '\n- ')
  .replace(/<\/(p|div|h[1-6]|ul|ol|li)>/gi, '\n')
  .replace(/<[^>]+>/g, ''))
  .replace(/[ \t]+/g, ' ').replace(/\n\s*\n\s*\n+/g, '\n\n').trim();
const asList = (v) => {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string' && v.startsWith('[')) { try { return JSON.parse(v.replace(/'/g, '"')); } catch (e) { /* fall through */ } }
  return v ? [v] : [];
};
const iso = (d) => (d && !isNaN(d) ? new Date(d).toISOString().slice(0, 10) : '');

const scraped = [];
const sourceErrors = [];
for (const { json } of $input.all()) {
  if (json.error) { sourceErrors.push(String(json.error.message || json.error).slice(0, 200)); continue; }
  // Himalayas: { totalCount, jobs: [...] }
  if (Array.isArray(json.jobs) && json.totalCount !== undefined) {
    for (const j of json.jobs) {
      const locs = asList(j.locationRestrictions);
      scraped.push({
        source: 'Himalayas', url: j.guid || j.applicationLink, title: j.title, company: j.companyName,
        location: locs.length ? `Remote (${locs.join(', ')})` : 'Remote (Worldwide)',
        description: htmlToText(j.description), postedMs: Number(j.pubDate) * 1000,
      });
    }
  // Jobicy: { apiVersion, jobs: [...] }
  } else if (Array.isArray(json.jobs) && json.apiVersion) {
    for (const j of json.jobs) {
      scraped.push({
        source: 'Jobicy', url: j.url, title: decode(j.jobTitle), company: decode(j.companyName),
        location: `Remote (${j.jobGeo || 'Worldwide'})`,
        description: htmlToText(j.jobDescription), postedMs: Date.parse(j.pubDate),
      });
    }
  // RemoteOK: one item per job (first item is the legal notice and has no position)
  } else if (json.position && json.url) {
    scraped.push({
      source: 'RemoteOK', url: json.url, title: decode(json.position), company: decode(json.company),
      location: json.location ? `Remote (${json.location})` : 'Remote',
      description: htmlToText(json.description), postedMs: Number(json.epoch) * 1000,
    });
  }
}

// Already processed URLs (Leads + Rejected tabs)
const seen = new Set();
for (const node of ['Read Leads', 'Read Rejected']) {
  for (const { json } of $(node).all()) if (json['Job Posting URL']) seen.add(String(json['Job Posting URL']).trim());
}

const hasAny = (text, words) => words.some((w) => text.includes(w));
const unique = new Map();
let passedKeyword = 0, alreadySeen = 0;
for (const j of scraped) {
  if (!j.url || !j.title || unique.has(j.url)) continue;
  const title = j.title.toLowerCase();
  const company = String(j.company || '').toLowerCase();
  const ageDays = (now - j.postedMs) / 86400000;
  if (!hasAny(title, config.includeKeywords)) continue;
  if (hasAny(title, config.excludeKeywords)) continue;
  if (config.excludedCompanies.some((c) => company.includes(c))) continue;
  if (j.postedMs && ageDays > config.maxAgeDays) continue;
  passedKeyword++;
  if (seen.has(j.url)) { alreadySeen++; continue; }
  unique.set(j.url, j);
}

const ready = [...unique.values()].sort((a, b) => (b.postedMs || 0) - (a.postedMs || 0));
const candidates = ready.slice(0, config.maxJobsPerRun).map((j) => ({
  url: j.url, title: j.title, company: j.company || 'Unknown', location: j.location, source: j.source,
  datePosted: iso(j.postedMs), description: j.description.slice(0, 30000),
}));

return [{
  json: {
    stats: {
      fetched: scraped.length, passedKeyword, alreadySeen,
      sentToLLM: candidates.length, deferredToNextRun: Math.max(0, ready.length - candidates.length),
      sourceErrors,
    },
    candidates,
    scraped: scraped.map((j) => ({ ...j, datePosted: iso(j.postedMs), postedMs: undefined })),
  },
}];

// Prepare AI Check  (runs once per job)
// Fills the validation prompt template from the Prompts tab with this job's details and builds
// two requests: one for OpenRouter (primary) and one for Cloudflare Workers AI (backup).

const config = $('Build Search Plan').first().json.config;
const fill = (tpl, vars) => tpl.replace(/\{\{\s*(\w+)\s*\}\}/g, (m, k) => (k in vars ? String(vars[k]) : m));

const job = $json;
const messages = [{
  role: 'user',
  content: fill(config.validationPrompt, {
    job_title: job.title, company_name: job.company, location: job.location,
    job_description: job.description.slice(0, 6000),
  }),
}];

return {
  json: {
    ...job,
    validationRequest: {
      models: [config.validationModel, config.fallbackModel].filter(Boolean),
      temperature: 0,
      response_format: { type: 'json_object' },
      messages,
    },
    validationBackup: { model: config.backupModel, temperature: 0, max_tokens: 1500, messages },
  },
};

// Parse AI Check  (runs once per job)
// Reads the LLM's JSON verdict (from OpenRouter, or from the Cloudflare backup if OpenRouter failed)
// and decides: "lead" (all checks pass), "rejected", or "error" (both AI providers failed -> the job
// is NOT saved, so it is retried automatically on the next run).
// For leads it also prepares the outreach requests (primary + backup).

const config = $('Build Search Plan').first().json.config;
const job = $('Prepare AI Check').item.json;
const fill = (tpl, vars) => tpl.replace(/\{\{\s*(\w+)\s*\}\}/g, (m, k) => (k in vars ? String(vars[k]) : m));
const bool = (v) => v === true || String(v).toLowerCase() === 'true';
const provider = (model) => (String(model).startsWith('@cf/') ? 'Cloudflare' : 'OpenRouter');

const { validationRequest, validationBackup, ...base } = job;
const raw = $json.choices?.[0]?.message?.content;
let check = null;
if (raw) {
  const text = String(raw).replace(/<think>[\s\S]*?<\/think>/g, '');
  const match = text.match(/\{[\s\S]*\}/);
  try { check = match ? JSON.parse(match[0]) : null; } catch (e) { check = null; }
}

// An incomplete answer (missing fields or no reason) is treated as an error, never as a rejection,
// so a good job is never dropped because a model cut its reply short. It is retried next run.
const REQUIRED_KEYS = ['is_remote', 'is_english', 'is_relevant', 'is_agency', 'reason'];
if (check && (REQUIRED_KEYS.some((k) => !(k in check)) || !String(check.reason).trim())) check = null;

if (!check) {
  const why = $json.error ? JSON.stringify($json.error).slice(0, 300) : `Unreadable or incomplete model reply: ${String(raw).slice(0, 200)}`;
  return { json: { ...base, decision: 'error', error: why } };
}

const model = $json.model || config.backupModel;
const verdict = {
  remote: bool(check.is_remote),
  english: bool(check.is_english),
  relevant: bool(check.is_relevant),
  agency: bool(check.is_agency),
  languages: String(check.language_requirements || 'English'),
  reason: String(check.reason || ''),
  model: `${model} (${provider(model)})`,
};
const isLead = verdict.remote && verdict.english && verdict.relevant && !(config.excludeAgencies && verdict.agency);

const out = { ...base, verdict, decision: isLead ? 'lead' : 'rejected' };
if (isLead) {
  const messages = [{
    role: 'user',
    content: fill(config.outreachPrompt, {
      ...config.sender,
      job_title: job.title, company_name: job.company, location: job.location,
      language_requirements: verdict.languages, job_description: job.description.slice(0, 6000),
    }),
  }];
  out.outreachRequest = { models: [config.outreachModel, config.fallbackModel].filter(Boolean), temperature: 0.7, messages };
  out.outreachBackup = { model: config.backupModel, temperature: 0.7, max_tokens: 2500, messages };
}
return { json: out };

// Format Lead
// Pairs each generated message (from OpenRouter or the Cloudflare backup) with its job and maps it
// to the Leads tab columns. If both AI providers failed, the job is skipped and retried next run.

const config = $('Build Search Plan').first().json.config;
const today = new Date().toISOString().slice(0, 10);
const provider = (model) => (String(model).startsWith('@cf/') ? 'Cloudflare' : 'OpenRouter');

const clean = (t) => String(t || '')
  .replace(/<think>[\s\S]*?<\/think>/g, '')
  .replace(/[‐‑]/g, '-').replace(/[  ]/g, ' ') // non-breaking hyphens/spaces some models emit
  .replace(/^```[a-z]*\n?|```$/gim, '')
  .replace(/\*\*(.*?)\*\*/g, '$1')
  .trim();

return $input.all().flatMap((item, i) => {
  const job = $('Is it a match?').itemMatching(i).json;
  let message = clean(item.json.choices?.[0]?.message?.content);
  if (!message || message.length < 80) return [];
  // Same ending whatever the model wrote: body, blank line, call to action, blank line, signature.
  const { call_to_action: cta, sender_name: name, sender_company: company } = config.sender;
  if (cta) message = message.split(cta).join('');
  const signatureLines = [name, company].filter(Boolean).map((s) => s.trim());
  message = message.split('\n').map((l) => l.trimEnd()).filter((l) => !signatureLines.includes(l.trim()))
    .join('\n').replace(/\n{3,}/g, '\n\n').trim();
  message = [message, cta, signatureLines.join('\n')].filter(Boolean).join('\n\n');
  const model = item.json.model || config.backupModel;
  return [{
    json: {
      'Job Posting URL': job.url,
      'Job Title': job.title,
      'Company Name': job.company,
      'Location': job.location,
      // One line keeps rows compact in the sheet; the full formatted text is in the run JSON.
      'Job Description': job.description.replace(/\s*\n+\s*/g, ' | ').replace(/^- /, ''),
      'LLM-Generated Outreach Message': message,
      'Language Requirements': job.verdict.languages,
      'Source': job.source,
      'Date Posted': job.datePosted,
      'Date Found': today,
      'Prompt Used': config.outreachPromptName,
      'AI Model': `${model} (${provider(model)})`,
      'Status': 'New',
      'Notes': '',
    },
  }];
});

// Format Rejection
// Maps jobs the AI rejected to the Rejected tab columns. LLM errors are dropped here
// (not saved), so those jobs are automatically retried on the next run.

const today = new Date().toISOString().slice(0, 10);
const yn = (b) => (b ? 'Yes' : 'No');

return $input.all()
  .filter((i) => i.json.decision === 'rejected')
  .map(({ json: j }) => ({
    json: {
      'Job Posting URL': j.url,
      'Job Title': j.title,
      'Company Name': j.company,
      'Location': j.location,
      'Remote': yn(j.verdict.remote),
      'English': yn(j.verdict.english),
      'Relevant': yn(j.verdict.relevant),
      'Agency': yn(j.verdict.agency),
      'Reason': j.verdict.reason,
      'Source': j.source,
      'Date Checked': today,
      'AI Model': j.verdict.model,
    },
  }));

// Summarize Run
// Runs last (bottom branch). Counts what happened and builds the Run Log row.
// Uses try/catch because branches with zero jobs never execute.

const count = (node, filter = () => true) => {
  try { return $(node).all().filter(filter).length; } catch (e) { return 0; }
};
const stats = $('Normalize & Filter').first().json.stats;
const cfOk = (i) => !i.json.error;

return [{
  json: {
    'Run Time (UTC)': new Date().toISOString().replace('T', ' ').slice(0, 16),
    'Trigger': $('Config').first().json.trigger || 'Manual',
    'Fetched': stats.fetched,
    'Passed Keyword Filter': stats.passedKeyword,
    'Already Seen': stats.alreadySeen,
    'Checked by LLM': stats.sentToLLM,
    'Leads Added': count('Add to Leads'),
    'Rejected': count('Add to Rejected'),
    'LLM Errors': count('Parse AI Check', (i) => i.json.decision === 'error'),
    'Backup AI Used': count('Backup AI: Validate', cfOk) + count('Backup AI: Write Outreach', cfOk),
  },
}];

// Build Run Report
// Creates the structured JSON record of this run (every scraped posting + every AI decision)
// which the next nodes save to disk as /files/job-run-<timestamp>.json

const safe = (node) => { try { return $(node).all().map((i) => i.json); } catch (e) { return []; } };
const norm = $('Normalize & Filter').first().json;

const decisions = safe('Parse AI Check').map(({ outreachRequest, outreachBackup, description, ...j }) => j);
const messages = Object.fromEntries(safe('Format Lead').map((l) => [l['Job Posting URL'], l['LLM-Generated Outreach Message']]));
for (const d of decisions) if (messages[d.url]) d.outreachMessage = messages[d.url];

return [{
  json: {
    runAt: new Date().toISOString(),
    summary: $('Summarize Run').first().json,
    stats: norm.stats,
    decisions,
    scraped: norm.scraped,
  },
}];
